#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long u64;
typedef unsigned __int128 u128;

// Non-negative big integer, base 2^64, little-endian limbs; empty means 0.
typedef vector<u64> Big;

void trim(Big &v) {
    while (!v.empty() && v.back() == 0) v.pop_back();
}

void mulSmall(Big &v, u64 m) {
    u64 carry = 0;
    for (auto &x : v) {
        u128 cur = (u128)x * m + carry;
        x = (u64)cur;
        carry = (u64)(cur >> 64);
    }
    if (carry) v.push_back(carry);
}

// v /= d where d divides v exactly: shift out the power of two, then divide by the
// odd part with its inverse mod 2^64 (bottom-up, no hardware division).
void divExact(Big &v, u64 d) {
    int tz = __builtin_ctzll(d);
    if (tz) {
        for (size_t i = 0; i < v.size(); i++)
            v[i] = (v[i] >> tz) | (i + 1 < v.size() ? v[i + 1] << (64 - tz) : 0);
        d >>= tz;
    }
    if (d != 1) {
        u64 inv = d;  // Newton iteration: each step doubles the correct low bits
        for (int i = 0; i < 6; i++) inv *= 2 - d * inv;
        u64 borrow = 0;
        for (auto &x : v) {
            u64 t = x - borrow, c = x < borrow;
            u64 q = t * inv;
            x = q;
            borrow = (u64)(((u128)q * d) >> 64) + c;
        }
    }
    trim(v);
}

void addTo(Big &a, const Big &b) {
    if (a.size() < b.size()) a.resize(b.size(), 0);
    u64 carry = 0;
    for (size_t i = 0; i < a.size(); i++) {
        if (i >= b.size() && !carry) break;
        u128 cur = (u128)a[i] + carry + (i < b.size() ? b[i] : 0);
        a[i] = (u64)cur;
        carry = (u64)(cur >> 64);
    }
    if (carry) a.push_back(carry);
}

u64 divRem(Big &v, u64 d) {  // v /= d, returns the remainder (used only for output)
    u64 rem = 0;
    for (int i = (int)v.size() - 1; i >= 0; i--) {
        u128 cur = ((u128)rem << 64) | v[i];
        v[i] = (u64)(cur / d);
        rem = (u64)(cur % d);
    }
    trim(v);
    return rem;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> f(n + 1, 0);  // f[t] = number of thresholds <= t
    for (int i = 0; i < n; i++) { int v; cin >> v; f[v]++; }
    for (int i = 1; i <= n; i++) f[i] += f[i - 1];
    Big answer;
    u64 small = 0;
    // r <= n - r: every threshold is forced, valid only when f[r] == f[n-r] == r.
    for (int r = 0; r <= n / 2; r++) small += f[r] == r && f[n - r] == r;
    if (small) answer.push_back(small);
    // r > n - r: M robots are free and exactly K of them must run, giving C(M, K).
    // M and K never decrease, so C(M, K) is updated by neighbouring-ratio steps.
    // Start at r = n/2 + 1 with C(M, 0) = 1 and let the loop walk K up; K may start negative
    // (more thresholds than r are <= n - r), giving 0.
    int start = n / 2 + 1;
    long long M = start <= n ? f[start] - f[n - start] : 0, K = start <= n ? start - f[n - start] : 0;
    Big value;
    if (0 <= K && K <= M) { K = 0; value.push_back(1); }
    u64 num = 1, den = 1;  // pending factor num / den not yet applied to value
    const u64 LIMIT = ~0ULL;
    auto flush = [&]() {
        if (num != 1) mulSmall(value, num);
        if (den != 1) divExact(value, den);
        num = den = 1;
    };
    auto step = [&](u64 a, u64 b) {  // value = value * a / b
        if (value.empty()) return;
        if (num > LIMIT / a || den > LIMIT / b) flush();
        num *= a;
        den *= b;
    };
    auto set = [&](u64 v) { num = den = 1; value.clear(); if (v) value.push_back(v); };
    for (int r = start; r <= n; r++) {
        long long targetM = f[r] - f[n - r], targetK = r - f[n - r];
        while (M < targetM) {
            M++;
            if (K == M) set(1);
            else if (0 <= K && K < M) step(M, M - K);  // C(M,K) = C(M-1,K) * M / (M-K)
            else set(0);
        }
        while (K < targetK) {
            K++;
            if (K == 0) set(1);
            else if (0 < K && K <= M) step(M - K + 1, K);  // C(M,K) = C(M,K-1) * (M-K+1) / K
            else set(0);
        }
        flush();
        addTo(answer, value);
    }
    // Convert to decimal, eighteen digits at a time.
    const u64 CHUNK = 1000000000000000000ULL;
    vector<u64> chunks;
    while (!answer.empty()) chunks.push_back(divRem(answer, CHUNK));
    if (chunks.empty()) { cout << "0\n"; return 0; }
    string out = to_string(chunks.back());
    char buf[24];
    for (int i = (int)chunks.size() - 2; i >= 0; i--) { snprintf(buf, sizeof buf, "%018llu", chunks[i]); out += buf; }
    cout << out << "\n";
}

import java.io.*;
import java.math.BigInteger;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    // Non-negative big integers as unsigned base-2^64 little-endian limbs with explicit lengths.
    static long[] value, answer;
    static int valueLen, answerLen;

    static void mulSmall(long m) {
        long carry = 0;
        for (int i = 0; i < valueLen; i++) {
            long lo = value[i] * m;
            long hi = Math.unsignedMultiplyHigh(value[i], m);
            lo += carry;
            if (Long.compareUnsigned(lo, carry) < 0) hi++;
            value[i] = lo;
            carry = hi;
        }
        if (carry != 0) value[valueLen++] = carry;
    }

    // value /= d where d divides value exactly: shift out the power of two, then divide by the
    // odd part with its inverse mod 2^64 (bottom-up, no hardware division).
    static void divExact(long d) {
        int tz = Long.numberOfTrailingZeros(d);
        if (tz > 0) {
            for (int i = 0; i < valueLen; i++)
                value[i] = (value[i] >>> tz) | (i + 1 < valueLen ? value[i + 1] << (64 - tz) : 0);
            d >>>= tz;
        }
        if (d != 1) {
            long inv = d;  // Newton iteration: each step doubles the correct low bits
            for (int i = 0; i < 6; i++) inv *= 2 - d * inv;
            long borrow = 0;
            for (int i = 0; i < valueLen; i++) {
                long x = value[i];
                long c = Long.compareUnsigned(x, borrow) < 0 ? 1 : 0;
                long q = (x - borrow) * inv;
                value[i] = q;
                borrow = Math.unsignedMultiplyHigh(q, d) + c;
            }
        }
        while (valueLen > 0 && value[valueLen - 1] == 0) valueLen--;
    }

    static void addValueToAnswer() {
        long carry = 0;
        int i = 0;
        for (; i < valueLen || carry != 0; i++) {
            if (i == answerLen) answer[answerLen++] = 0;
            long b = i < valueLen ? value[i] : 0;
            long s = answer[i] + b;
            long c1 = Long.compareUnsigned(s, b) < 0 ? 1 : 0;
            long t = s + carry;
            long c2 = Long.compareUnsigned(t, s) < 0 ? 1 : 0;
            answer[i] = t;
            carry = c1 + c2;
        }
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] f = new long[n + 1];  // f[t] = number of thresholds <= t
        for (int i = 0; i < n; i++) f[nextInt()]++;
        for (int i = 1; i <= n; i++) f[i] += f[i - 1];
        value = new long[n / 64 + 8];
        answer = new long[n / 64 + 8];
        long small = 0;
        // r <= n - r: every threshold is forced, valid only when f[r] == f[n-r] == r.
        for (int r = 0; r <= n / 2; r++) if (f[r] == r && f[n - r] == r) small++;
        if (small > 0) answer[answerLen++] = small;
        // r > n - r: M robots are free and exactly K of them must run, giving C(M, K).
        // M and K never decrease, so C(M, K) is updated by neighbouring-ratio steps,
        // batched as a pending factor num / den (each below 2^63).
        // Start at r = n/2 + 1 with C(M, 0) = 1 and let the loop walk K up; K may start negative
        // (more thresholds than r are <= n - r), giving 0.
        int start = n / 2 + 1;
        long M = start <= n ? f[start] - f[n - start] : 0, K = start <= n ? start - f[n - start] : 0;
        long num = 1, den = 1;
        if (0 <= K && K <= M) {
            K = 0;
            value[valueLen++] = 1;
        }
        for (int r = start; r <= n; r++) {
            long targetM = f[r] - f[n - r], targetK = r - f[n - r];
            while (M < targetM || K < targetK) {
                long a = 0, b = 0;
                if (M < targetM) {
                    M++;
                    if (K == M) { num = den = 1; valueLen = 0; value[valueLen++] = 1; }
                    else if (0 <= K && K < M) { a = M; b = M - K; }  // C(M,K) = C(M-1,K) * M / (M-K)
                    else { num = den = 1; valueLen = 0; }
                } else {
                    K++;
                    if (K == 0) { num = den = 1; valueLen = 0; value[valueLen++] = 1; }
                    else if (0 < K && K <= M) { a = M - K + 1; b = K; }  // C(M,K) = C(M,K-1) * (M-K+1) / K
                    else { num = den = 1; valueLen = 0; }
                }
                if (a == 0 || valueLen == 0) continue;
                if (num > Long.MAX_VALUE / a || den > Long.MAX_VALUE / b) {
                    mulSmall(num);
                    divExact(den);
                    num = den = 1;
                }
                num *= a;
                den *= b;
            }
            if (num != 1) mulSmall(num);
            if (den != 1) divExact(den);
            num = den = 1;
            addValueToAnswer();
        }
        byte[] bytes = new byte[answerLen * 8 + 1];  // big-endian magnitude with a zero sign byte
        for (int i = 0; i < answerLen; i++)
            for (int j = 0; j < 8; j++) bytes[bytes.length - 1 - (i * 8 + j)] = (byte) (answer[i] >>> (8 * j));
        System.out.println(new BigInteger(bytes));
    }
}

package main

import (
	"bufio"
	"io"
	"math/big"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	f := make([]int64, n+1) // f[t] = number of thresholds <= t
	for i := 0; i < n; i++ {
		f[nextInt()]++
	}
	for i := 1; i <= n; i++ {
		f[i] += f[i-1]
	}
	small := int64(0)
	// r <= n - r: every threshold is forced, valid only when f[r] == f[n-r] == r.
	for r := 0; r <= n/2; r++ {
		if f[r] == int64(r) && f[n-r] == int64(r) {
			small++
		}
	}
	answer := big.NewInt(small)
	// r > n - r: M robots are free and exactly K of them must run, giving C(M, K).
	// M and K never decrease, so C(M, K) is updated by neighbouring-ratio steps.
	// Start at r = n/2 + 1 with C(M, 0) = 1 and let the loop walk K up; K may start negative
	// (more thresholds than r are <= n - r), giving 0.
	start := n/2 + 1
	var M, K int64
	if start <= n {
		M, K = f[start]-f[n-start], int64(start)-f[n-start]
	}
	value := big.NewInt(0)
	if 0 <= K && K <= M {
		K = 0
		value.SetInt64(1)
	}
	factor := new(big.Int)
	step := func(a, b int64) { // value = value * a / b (exact)
		if value.Sign() == 0 {
			return
		}
		value.Mul(value, factor.SetInt64(a))
		value.Quo(value, factor.SetInt64(b))
	}
	for r := start; r <= n; r++ {
		targetM, targetK := f[r]-f[n-r], int64(r)-f[n-r]
		for M < targetM {
			M++
			if K == M {
				value.SetInt64(1)
			} else if 0 <= K && K < M {
				step(M, M-K) // C(M,K) = C(M-1,K) * M / (M-K)
			} else {
				value.SetInt64(0)
			}
		}
		for K < targetK {
			K++
			if K == 0 {
				value.SetInt64(1)
			} else if 0 < K && K <= M {
				step(M-K+1, K) // C(M,K) = C(M,K-1) * (M-K+1) / K
			} else {
				value.SetInt64(0)
			}
		}
		answer.Add(answer, value)
	}
	os.Stdout.WriteString(answer.String() + "\n")
}
